    /// 세션에 기록된 Playwright 구성 지문. 세션이 없으면 nil, 기록이 없으면 "".
    static func playwrightFingerprint(session: String) -> String? {
        guard run(["has-session", "-t", "=\(session)"]) == 0 else { return nil }
        // -q 는 세션이 없어도 0 으로 끝나므로 위에서 먼저 확인한다
        guard let value = output(["show-options", "-v", "-q", "-t", "=\(session):", PlaywrightMCP.sessionOption]) else { return nil }
        return value.trimmingCharacters(in: .newlines)
    }

